import sys
from collections import Counter

RANK_ORDER = '23456789TJQKA'

def parse_hand(cards):
    ranks = [c[0] for c in cards]
    suits = [c[1] for c in cards]
    return ranks, suits

def rank_value(r):
    return RANK_ORDER.index(r)

def evaluate_hand(hand):
    ranks, suits = parse_hand(hand)
    rank_counts = Counter(ranks)

    is_flush = len(set(suits)) == 1

    sorted_ranks = sorted(ranks, key=lambda x: rank_value(x), reverse=True)
    unique_ranks = sorted(set(ranks), key=lambda x: rank_value(x), reverse=True)

    unique_sorted = sorted(unique_ranks, key=lambda x: RANK_ORDER.index(x))
    is_straight = len(unique_ranks) == 5 and (rank_value(unique_sorted[-1]) - rank_value(unique_sorted[0]) == 4)

    straight_high = None
    if is_straight:
        straight_high = rank_value(unique_sorted[-1])
    elif unique_sorted == ['A', '2', '3', '4', '5']:
        is_straight = True
        straight_high = rank_value('5')

    if is_straight and is_flush:
        return (8, straight_high)

    four = [r for r, c in rank_counts.items() if c == 4]
    three = [r for r, c in rank_counts.items() if c == 3]
    pairs = [r for r, c in rank_counts.items() if c == 2]

    if four:
        four_val = rank_value(four[0])
        kicker = [r for r in sorted_ranks if r != four[0]][0]
        return (7, four_val, rank_value(kicker))

    if three and len(pairs) == 1:
        three_val = rank_value(three[0])
        pair_val = rank_value(pairs[0])
        return (6, three_val, pair_val)

    if is_flush:
        flush_vals = [rank_value(r) for r in ranks]
        return (5, flush_vals[0], flush_vals[1], flush_vals[2], flush_vals[3], flush_vals[4])

    if is_straight:
        return (4, straight_high)

    if len(pairs) == 2:
        pair_vals = sorted([rank_value(p) for p in pairs], reverse=True)
        kicker = [r for r in ranks if r not in pairs][0]
        return (3, pair_vals[0], pair_vals[1], rank_value(kicker))

    if three:
        three_val = rank_value(three[0])
        kickers = [rank_value(r) for r in sorted_ranks if r != three[0]]
        return (2, three_val, kickers[0], kickers[1])

    if len(pairs) == 1:
        pair_val = rank_value(pairs[0])
        kickers = [rank_value(r) for r in sorted_ranks if r != pairs[0]]
        return (1, pair_val, kickers[0], kickers[1], kickers[2])

    high_vals = [rank_value(r) for r in ranks]
    return (0, high_vals[0], high_vals[1], high_vals[2], high_vals[3], high_vals[4])

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    cards = line.split()
    black_hand = cards[:5]
    white_hand = cards[5:]

    black_eval = evaluate_hand(black_hand)
    white_eval = evaluate_hand(white_hand)

    if black_eval > white_eval:
        print("Black wins")
    elif black_eval < white_eval:
        print("White wins")
    else:
        print("Tie")
